{
  "edits": [
    {
      "original": "Access checks default to fail-closed, rather than open.",
      "replacement": "Access checks default to fail-closed: when verification does not complete, access is denied. A failed check never grants entry.",
      "reason": "\"open\" is not the ordinary, general-knowledge antonym of \"fail-closed\" (it is security jargon), so the trailer is smuggling a genuine distinction into a bolted-on clause; the distinction is rewritten as its own sentence stated as what the check does."
    },
    {
      "original": "Those privilege limits are imposed on purpose, rather than by accident.",
      "replacement": "Those privilege limits are imposed on purpose.",
      "reason": "\"by accident\" is the ordinary antonym of \"on purpose\" that anyone would know, so the trailer adds nothing and is cut."
    }
  ]
}

